select set_config('request.jwt.claim.role','service_role',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update public.quiz_attempts set deadline_at=clock_timestamp()+interval '1 second' where id='b1101001-5a11-4b11-8c11-000000000201' and student_id='b1101001-5a11-4b11-8c11-000000000002' and status='in_progress';
