do $observe$
declare seen jsonb; until_time timestamptz := clock_timestamp()+interval '14 seconds';
begin
 loop
  perform pg_stat_clear_snapshot();
  select jsonb_agg(jsonb_build_object('pidA',pg_backend_pid(),'pidB',a.pid,
    'waitEventType',a.wait_event_type,'waitEvent',a.wait_event,
    'blockingPids',pg_blocking_pids(a.pid),'observedAt',clock_timestamp(),
    'isExpectedRpc',a.query like '%expire_quiz_attempt%')) into seen
  from pg_stat_activity a where a.pid<>pg_backend_pid()
    and pg_backend_pid()=any(pg_blocking_pids(a.pid)) and a.query like '%expire_quiz_attempt%';
  if seen is not null then
   perform set_config('m11.observed',seen::text,true); exit;
  end if;
  if clock_timestamp()>=until_time then raise exception 'm11_actual_lock_not_observed'; end if;
  perform pg_sleep(0.1);
 end loop;
end $observe$;
